import os
import subprocess
import urllib.request
import ipaddress
import socket
from urllib.parse import urlparse
from mcp.server.fastmcp import FastMCP
from db import run_query

mcp = FastMCP(
    "team-tools",
    transport="streamable-http",
    host=os.environ.get("MCP_HOST", "127.0.0.1"),
    port=int(os.environ.get("MCP_PORT", 8000)),
    auth_token=os.environ.get("MCP_TOKEN"),
)

DOCS = os.path.realpath("/srv/docs")
DB_URL = os.environ["DATABASE_URL"]

ALLOWED_HOSTS = os.environ.get("ALLOWED_HOSTS", "").split(",")


def _is_safe_url(url: str) -> bool:
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return False
    hostname = parsed.hostname
    if not hostname:
        return False

    if ALLOWED_HOSTS and hostname not in ALLOWED_HOSTS:
        return False

    try:
        ip_str = socket.gethostbyname(hostname)
        ip = ipaddress.ip_address(ip_str)
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast:
            return False
    except Exception:
        return False
    return True


@mcp.tool()
def read_doc(path: str) -> str:
    """Read a document from the shared docs folder."""
    if not path or len(path) > 255:
        raise ValueError("Invalid path length.")

    target_path = os.path.realpath(os.path.join(DOCS, path))
    if not target_path.startswith(DOCS + os.sep) and target_path != DOCS:
        raise ValueError("Access denied: path outside allowed directory.")

    if not os.path.exists(target_path) or not os.path.isfile(target_path):
        raise ValueError(f"File not found: {path}")

    with open(target_path, "r", encoding="utf-8") as f:
        return f.read()


@mcp.tool()
def fetch(url: str) -> str:
    """Fetch an allowed external web page."""
    if not _is_safe_url(url):
        raise ValueError("URL is not permitted or targets a restricted network.")

    req = urllib.request.Request(url, headers={"User-Agent": "TeamToolsMCP/1.0"})
    with urllib.request.urlopen(req, timeout=10) as response:
        return response.read().decode("utf-8", errors="ignore")


@mcp.tool()
def grep_logs(pattern: str) -> str:
    """Search today's application log safely."""
    if not pattern or len(pattern) > 100:
        raise ValueError("Invalid or excessively long search pattern.")

    log_path = "/var/log/app.log"
    if not os.path.exists(log_path):
        raise ValueError("Log file not available.")

    try:
        result = subprocess.run(
            ["grep", pattern, log_path],
            capture_output=True,
            text=True,
            check=False,
            timeout=5
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return "Search timed out."


@mcp.tool()
