# Helper function to compute Reciprocal Rank (RR) and Hit Rate @ 1 (HR@1)
# RR is 1 / position of the expected document (1-indexed), or 0 if not found.
def evaluate(filepath):
    total_queries = 0
    hits_at_1 = 0
    rr_sum = 0.0

    with open(filepath, 'r') as f:
        for line in f:
            data = json.loads(line.strip())
            expected = data['expected']
            ranked = data['ranked']
            total_queries += 1

            if expected in ranked:
                rank = ranked.index(expected) + 1
                rr_sum += 1.0 / rank
                if rank == 1:
                    hits_at_1 += 1

